/* ============================================================
 * DIM: L3 分类维表 —— 全量 (schema v1.4.30)
 *
 * dim.dim_l3_classify_all：全部 L1/L2/L3；含 icpdf_match_*，供通用分类与回填脚本使用。
 * dim.dim_l3_classify：电阻专用窄表（无 icpdf_match_*），见 sql_scripts/分类/dim_l3_classify.sql。
 *
 * 维护：本文件手工维护（schema 版本号常量见 gen_dim_schema_v1430.py）；勿覆盖 sql_scripts/分类/dim_l3_classify.sql。
 * ============================================================ */

CREATE TABLE IF NOT EXISTS dim.dim_l3_classify_all (
    `l3_id`                        VARCHAR(6)    NOT NULL COMMENT '六位数字主键：L1两位+L2两位+L3两位序号拼接',
    `l1_code`                      VARCHAR(64)   NOT NULL COMMENT 'L1 英文编码（小写蛇形）',
    `l1_cn`                        VARCHAR(128)  NULL     COMMENT 'L1 中文名称',
    `l2_code`                      VARCHAR(96)   NOT NULL COMMENT 'L2 英文编码（小写蛇形）',
    `l2_cn`                        VARCHAR(256)  NULL     COMMENT 'L2 中文名称',
    `l3_code`                      VARCHAR(64)   NOT NULL COMMENT 'L3 英文编码短名（snake_case，全局勿单独作主键）',
    `l3_cn`                        VARCHAR(256)  NULL     COMMENT 'L3 中文名称',

    `icpdf_match_category`         ARRAY<VARCHAR(128)> NULL COMMENT 'p1：与 icpdf param.category 精确匹配的种子',
    `icpdf_match_category2`       ARRAY<VARCHAR(128)> NULL COMMENT 'p2：与 category2 精确匹配的种子',
    `icpdf_match_category_info`    ARRAY<VARCHAR(128)> NULL COMMENT 'p3：与 category_info 数组求交集的种子',
    `icpdf_match_taginfo`          ARRAY<VARCHAR(128)> NULL COMMENT 'p4：与 taginfo 数组求交集的种子',
    `icpdf_match_partno_prefix`    ARRAY<VARCHAR(32)>  NULL COMMENT 'p5：料号前缀兜底',

    `note`                         VARCHAR(512)  NULL     COMMENT '备注（如 raw=L3 原始英文名）',
    `schema_version`               VARCHAR(32)   NOT NULL COMMENT '字典版本号（非主键）',
    `create_at`                    DATETIME      NULL     DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_at`                    DATETIME      NULL     DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=OLAP
PRIMARY KEY(`l3_id`)
COMMENT 'L3 分类维表（全量）'
DISTRIBUTED BY HASH(`l3_id`) BUCKETS 1
PROPERTIES ("replication_num" = "1", "enable_persistent_index" = "true");


